<span id="share-records" class="platform-section" aria-hidden="true"></span>
<section class="card"><h2><?= e(t('Share selected people records & attachments')) ?></h2><p><?= e(t('Choose exactly which contacts/documents to share with a paired device. These fields and attachment bytes are end-to-end encrypted. Previous local document versions remain when an incoming version is accepted. Maximum combined attachment size: 5 MiB per packet.')) ?></p><form method="post" action="/platform/objects/export"><?= csrf_field() ?><label><?= e(t('Paired device')) ?><select name="peer" required><?php foreach(Db::all('SELECT * FROM platform_peers WHERE revoked=0')as $peer): ?><option value="<?= e($peer['id']) ?>"><?= e($peer['name']) ?></option><?php endforeach; ?></select></label><fieldset><legend><?= e(t('People records, including their private notes and birthdays')) ?></legend><?php if(module_enabled('LifePlanning'))foreach(LifePlanningService::rows('contacts')as $contact): ?><label><input type="checkbox" name="contacts[]" value="<?= e($contact['id']) ?>"> <?= e($contact['name']) ?></label><?php endforeach; ?></fieldset><fieldset><legend><?= e(t('Document files and metadata')) ?></legend><?php if(module_enabled('Documents'))foreach(Db::all('SELECT id,title,bytes FROM documents WHERE deleted_at IS NULL ORDER BY title')as $document): ?><label><input type="checkbox" name="documents[]" value="<?= e($document['id']) ?>"> <?= e($document['title']) ?> · <?= e($document['bytes']) ?> <?= e(t('bytes')) ?></label><?php endforeach; ?></fieldset><button><?= e(t('Encrypt selected records for device')) ?></button></form><form method="post" action="/platform/objects/preview" enctype="multipart/form-data"><?= csrf_field() ?><label><?= e(t('Received record packet')) ?><input type="file" name="file" accept=".json"></label><label><?= e(t('Or paste packet')) ?><textarea name="packet" rows="4" maxlength="12582912"></textarea></label><button><?= e(t('Authenticate & preview records')) ?></button></form></section>
